  st=_reset(obs);step=_step(obs);n=len(list(_g(_farm(obs),'hands',[]) or []));streams={e:[list(_R[e][step].get('farmer') or ['PASS']),*[list(x or ['PASS']) for x in _R[e][step].get('hands',[])]] for e in _R};out=[]
